    <style>
        :root {
            --primary-green: #1a5c3a;
            --dark-green: #0f3d26;
            --light-bg: #f4f7f5;
            --text-main: #333;
            --text-muted: #666;
            --white: #ffffff;
            --card-shadow: 0 10px 30px rgba(0,0,0,0.15);
            --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: var(--font-family);
            background-color: var(--light-bg);
            color: var(--text-main);
            overflow-x: hidden; /* Prevent horizontal scroll from floating elements */
        }

        /* --- Header / Navbar --- */
        .navbar {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 70px;
            background-color: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(10px);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 40px;
            z-index: 1000;
            border-bottom: 1px solid rgba(0,0,0,0.05);
        }

        .logo-area {
            display: flex;
            align-items: center;
            gap: 10px;
            font-weight: 700;
            color: var(--primary-green);
            font-size: 1.2rem;
        }

        .logo-icon {
            width: 32px;
            height: 32px;
            background: #2ea865;
            color: white;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
        }

        .nav-links {
            display: flex;
            gap: 25px;
            list-style: none;
        }

        .nav-links a {
            text-decoration: none;
            color: var(--text-main);
            font-weight: 500;
            font-size: 0.95rem;
            transition: color 0.2s;
        }

        .nav-links a:hover {
            color: var(--primary-green);
        }

        .nav-actions {
            display: flex;
            gap: 12px;
        }

        .btn {
            padding: 10px 20px;
            border-radius: 50px;
            text-decoration: none;
            font-weight: 600;
            font-size: 0.9rem;
            cursor: pointer;
            transition: transform 0.2s, opacity 0.2s;
            border: none;
            display: inline-flex;
            align-items: center;
            gap: 6px;
        }

        .btn-outline {
            background: white;
            color: var(--text-main);
            border: 1px solid #ddd;
        }

        .btn-primary {
            background: #2ea865;
            color: white;
        }

        .btn:hover {
            transform: translateY(-1px);
            opacity: 0.9;
        }

        /* --- Hero Section (Top Green Box) --- */
        .hero-section {
            margin-top: 70px; /* Offset for fixed navbar */
            background: linear-gradient(135deg, #145c36 0%, #0d4025 100%);
