            text-align: center;
            color: white;
            border-bottom-left-radius: 30px;
            border-bottom-right-radius: 30px;
            position: relative;
            z-index: 10;
        }

        .hero-title {
            font-size: 2rem;
            font-weight: 800;
            margin-bottom: 16px;
            line-height: 1.3;
            max-width: 600px;
            margin-left: auto;
            margin-right: auto;
        }

        .hero-subtitle {
            font-size: 1rem;
            opacity: 0.85;
            max-width: 650px;
            margin: 0 auto 30px;
            line-height: 1.6;
        }

        .hero-actions {
            display: flex;
            justify-content: center;
            gap: 16px;
            flex-wrap: wrap;
            margin-bottom: 24px;
        }

